-- Упражнения книги 17, глава 17 (oVirt). Файл строит scratchpad/ovirt/builder.py; после правок можно редактировать и вручную.
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'virt-sim-ovirt-dc', 0, 'lab', 'Симулятор: поднимаем дата-центр oVirt', 'Соберите окружение oVirt так, как это делает администратор в Administration Portal: кластер, хосты, логическая сеть vm-net, домен хранилища и виртуальная машина. У каждого объекта свои состояния, и порядок действий важен: домен создаёт хост со статусом Up, дата-центр оживает только после активации главного домена, а сеть, обязательная для кластера, переводит хосты без неё в NonOperational. Упражнение решено, когда выполнены все три цели.', '', 'Начните с кластера и хоста. Сеть vm-net делает хосты без неё NonOperational — назначьте её на сетевые карты. Домен проходит три шага: создать, подключить, активировать. Чтобы хост ушёл в обслуживание, виртуальной машине нужен другой хост с её сетью.', '{}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'virt-sim-ovirt-topo', 1, 'lab', 'Доска: собираем окружение oVirt', 'На доске вы собираете окружение oVirt: добавляете движок, дата-центры, кластеры, хосты, логические сети, домены хранилища и виртуальные машины и соединяете их. Статусы выводятся из связей: хост без обязательной сети — NonOperational, без сети управления до движка — NonResponsive, дата-центр без активного главного домена — не Up. Кнопки «Путь сообщения» показывают, как команда движка идёт по сетям и где обрывается. В пяти сценариях соберите или почините окружение. Упражнение решено, когда цели всех сценариев выполнены.', '', 'Связь тянется от выхода одного объекта ко входу другого: движок → дата-центр → кластер → хост. Сеть определяют в дата-центре, подключают к кластеру и назначают на хост, а у движка должна быть карта в сети управления. Домен подключают к дата-центру и затем соединяют с каждым хостом. Нажмите на объект: справа будет причина его статуса.', '{}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'virt-sim-ovirt-clusters', 2, 'lab', 'Доска: кластеры и размещение', 'Собирайте среду oVirt на доске: кластеры, хосты, сети и машины. Пять сценариев: расставить машины по хостам так, чтобы каждую можно было мигрировать; подключить сеть ко всем трём кластерам; перенести хост из одного кластера в другой; вернуть в дата-центр кластер, который в него не входит; перенести кластер в другой дата-центр. Упражнение решено, когда решены все сценарии.', '', 'Кластер — граница живой миграции, дата-центр — граница сетей и хранилищ. Выберите объект, чтобы прочитать причину его статуса.', '{}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'virt-sim-ovirt-puzzles', 3, 'lab', 'Доска: головоломки иерархии', 'Пять головоломок на одной доске: среда без менеджера, сеть не в том дата-центре, машина с чужим диском, три дата-центра с оборванным путём менеджера и среда с тремя независимыми неисправностями. Читайте причины статусов и проверяйте путь команды. Упражнение решено, когда решены все сценарии.', '', 'Идите от симптома к причине: статус объекта, его причина, звено иерархии, которого не хватает.', '{}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-vm-path', 4, 'func', 'Где работает машина', 'Инвентарь oVirt — вложенные словари: центр данных → кластер → хост → список имён виртуальных машин, например {"dc1": {"cl1": {"h1": ["web", "db"]}}}. Напишите функцию vm_path(inventory, vm): верните строку вида "dc1/cl1/h1" для хоста, на котором работает машина vm, или пустую строку, если такой машины нет.', 'def vm_path(inventory, vm):
    pass
', 'Три вложенных цикла по items(); как только нашли имя в списке, собирайте путь.', '{"func": "vm_path", "tests": [{"args": [{"dc1": {"cl1": {"h1": ["web", "db"], "h2": ["cache"]}}}, "cache"], "expected": "dc1/cl1/h2"}, {"args": [{"dc1": {"cl1": {"h1": ["web"]}}}, "none"], "expected": ""}, {"args": [{}, "web"], "expected": ""}, {"args": [{"dc1": {"cl1": {"h1": []}}, "dc2": {"cl9": {"h7": ["x", "y"]}}}, "y"], "expected": "dc2/cl9/h7"}, {"args": [{"a": {"b": {"c": ["m"]}, "d": {"e": ["n"]}}}, "n"], "expected": "a/d/e"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-inventory-stats', 5, 'func', 'Счётчики инвентаря', 'Для инвентаря из прошлой задачи (центр данных → кластер → хост → список ВМ) напишите функцию inventory_stats(inventory): верните кортеж из четырёх чисел — сколько центров данных, кластеров, хостов и виртуальных машин в инвентаре.', 'def inventory_stats(inventory):
    pass
', 'Накапливайте четыре счётчика в тех же вложенных циклах.', '{"func": "inventory_stats", "tests": [{"args": [{}], "expected": {"__tuple__": [0, 0, 0, 0]}}, {"args": [{"dc1": {"cl1": {"h1": ["a", "b"], "h2": []}}}], "expected": {"__tuple__": [1, 1, 2, 2]}}, {"args": [{"dc1": {"cl1": {"h1": ["a"]}, "cl2": {"h2": ["b", "c", "d"]}}, "dc2": {}}], "expected": {"__tuple__": [2, 2, 2, 4]}}, {"args": [{"x": {"y": {}}}], "expected": {"__tuple__": [1, 1, 0, 0]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-cluster-baseline', 6, 'func', 'Базовый процессор кластера', 'Тип процессора кластера не может быть новее самого старого хоста. Даны generations — названия поколений процессоров от старого к новому, например ["Nehalem", "Sandy Bridge", "Haswell", "Skylake"], и host_cpus — поколения хостов кластера. Напишите функцию cluster_baseline(generations, host_cpus): верните самое старое поколение среди хостов. Если хостов нет, верните пустую строку.', 'def cluster_baseline(generations, host_cpus):
    pass
', 'Порядок поколения — это generations.index(name); берите минимум по этому ключу.', '{"func": "cluster_baseline", "tests": [{"args": [["Nehalem", "Sandy Bridge", "Haswell", "Skylake"], ["Haswell", "Skylake", "Haswell"]], "expected": "Haswell"}, {"args": [["Nehalem", "Sandy Bridge", "Haswell", "Skylake"], ["Skylake"]], "expected": "Skylake"}, {"args": [["Nehalem", "Sandy Bridge", "Haswell", "Skylake"], []], "expected": ""}, {"args": [["A", "B", "C"], ["C", "B", "C", "A", "B"]], "expected": "A"}, {"args": [["A", "B", "C"], ["B", "B"]], "expected": "B"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-api-url', 7, 'func', 'Адрес REST-запроса', 'REST-интерфейс менеджера живёт по адресу https://<хост>/ovirt-engine/api. Напишите функцию api_url(host, path, query): path — строка вроде "vms/123/start" (в начале и в конце могут быть лишние слэши, их надо убрать), query — словарь параметров. Верните полный адрес; параметры добавляйте после знака ?, отсортировав по имени и соединив через &, в виде имя=значение (значения — строки или числа, экранировать не нужно). Пустой query даёт адрес без ?; пустой path — адрес самого корня API без завершающего слэша.', 'def api_url(host, path, query):
    pass
', 'path.strip(''/''); если он пустой, не добавляйте слэш. Параметры: sorted(query.items()).', '{"func": "api_url", "tests": [{"args": ["engine.example.org", "vms", {}], "expected": "https://engine.example.org/ovirt-engine/api/vms"}, {"args": ["engine.example.org", "/vms/123/start/", {}], "expected": "https://engine.example.org/ovirt-engine/api/vms/123/start"}, {"args": ["e", "", {}], "expected": "https://e/ovirt-engine/api"}, {"args": ["e", "vms", {"search": "name=web", "max": 10}], "expected": "https://e/ovirt-engine/api/vms?max=10&search=name=web"}, {"args": ["e", "/", {"a": 1}], "expected": "https://e/ovirt-engine/api?a=1"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-host-states', 8, 'func', 'Состояния хоста', 'Упрощённая модель жизни хоста. Переходы (состояние, событие) → новое состояние: (Maintenance, activate) → Up; (Up, maintenance) → PreparingForMaintenance; (PreparingForMaintenance, vms_migrated) → Maintenance; (Up, no_heartbeat) → NonResponsive; (NonResponsive, heartbeat) → Up; (NonResponsive, fenced) → Reboot; (Reboot, heartbeat) → Up. Любое событие, для которого перехода нет, оставляет состояние прежним. Напишите функцию final_state(start, events): верните состояние после всех событий по порядку.', 'def final_state(start, events):
    pass
', 'Положите переходы в словарь с ключом-кортежем и берите table.get((state, event), state).', '{"func": "final_state", "tests": [{"args": ["Maintenance", []], "expected": "Maintenance"}, {"args": ["Maintenance", ["activate"]], "expected": "Up"}, {"args": ["Up", ["maintenance", "vms_migrated"]], "expected": "Maintenance"}, {"args": ["Up", ["no_heartbeat", "heartbeat"]], "expected": "Up"}, {"args": ["Up", ["no_heartbeat", "fenced", "activate"]], "expected": "Reboot"}, {"args": ["Up", ["no_heartbeat", "fenced", "heartbeat"]], "expected": "Up"}, {"args": ["Up", ["heartbeat", "activate"]], "expected": "Up"}, {"args": ["Up", ["maintenance", "heartbeat", "vms_migrated", "activate", "no_heartbeat"]], "expected": "NonResponsive"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-compat-version', 9, 'func', 'Версия совместимости', 'Версии записаны строками "4.7" (старшая и младшая части — целые числа, сравнивать надо как числа, так что "4.10" новее "4.9"). Кластер можно перевести на новую версию target, если выполнены три условия: target не ниже текущей версии кластера current, target не выше версии центра данных dc, и target не выше, чем поддерживает самый слабый хост (host_max — список максимальных версий хостов). Напишите функцию can_upgrade(current, target, dc, host_max): верните True или False.', 'def can_upgrade(current, target, dc, host_max):
    pass
', 'Превратите версию в кортеж чисел: tuple(map(int, s.split(''.''))); кортежи сравниваются как нужно.', '{"func": "can_upgrade", "tests": [{"args": ["4.6", "4.7", "4.7", ["4.7", "4.7"]], "expected": true}, {"args": ["4.6", "4.7", "4.6", ["4.7"]], "expected": false}, {"args": ["4.7", "4.6", "4.7", ["4.7"]], "expected": false}, {"args": ["4.6", "4.7", "4.7", ["4.7", "4.6"]], "expected": false}, {"args": ["4.9", "4.10", "4.10", ["4.10", "5.0"]], "expected": true}, {"args": ["4.9", "4.10", "4.9", ["4.10"]], "expected": false}, {"args": ["4.7", "4.7", "4.7", []], "expected": true}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-missing-ports', 10, 'func', 'Каких портов не хватает', 'Для работы платформы на хосте должны быть открыты порты: 22 (SSH), 54321 (VDSM), 16514 (libvirt по TLS) и диапазон 49152–49215 для миграции. Напишите функцию missing_ports(open_ports): open_ports — список открытых номеров и диапазонов (диапазон задан кортежем (от, до) включительно). Верните отсортированный список недостающих обязательных портов из первых трёх; диапазон миграции считается закрытым, если не покрыт открытыми диапазонами целиком, тогда добавьте в ответ его начало 49152 как признак. Порт из диапазона миграции, открытый по отдельности, диапазон не покрывает.', 'def missing_ports(open_ports):
    pass
', 'Для каждого обязательного порта проверьте: он равен числу в списке или лежит в каком-то кортеже. Диапазон миграции — достаточно одного кортежа, покрывающего 49152..49215.', '{"func": "missing_ports", "tests": [{"args": [[22, 54321, 16514, {"__tuple__": [49152, 49215]}]], "expected": []}, {"args": [[]], "expected": [22, 16514, 49152, 54321]}, {"args": [[22, 16514, {"__tuple__": [49000, 50000]}]], "expected": [54321]}, {"args": [[22, 54321, 16514, 49152, 49153]], "expected": [49152]}, {"args": [[{"__tuple__": [1, 65535]}]], "expected": []}, {"args": [[{"__tuple__": [20, 30]}, 54321, {"__tuple__": [49152, 49200]}]], "expected": [16514, 49152]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-ha-score', 11, 'func', 'Оценка хоста для hosted engine', 'Службы hosted engine выбирают для менеджера хост с лучшей оценкой. Упрощённая модель по мотивам настроек агента hosted engine: оценка начинается с 3400; если шлюз недоступен, вычитается 1600; если нет сети управления (моста управления), вычитается 600; если свободной памяти меньше 4096 МБ (порог — значение нашей модели), вычитается 400; штраф за загрузку процессора растёт линейно: до 40 процентов он нулевой, от 90 процентов равен 1000, а между ними равен (загрузка − 40) * 20. Оценка не бывает меньше нуля. Напишите функцию best_host(hosts): hosts — словарь имя → словарь с полями gateway (bool), mgmt (bool), free_mb (число), cpu (проценты). Верните имя хоста с наибольшей оценкой; при равенстве — меньшее имя в алфавитном порядке. Для пустого словаря верните пустую строку.', 'def best_host(hosts):
    pass
', 'Напишите отдельную функцию score(h) и возьмите max с ключом (оценка, минус имя) — или отсортируйте по (-оценка, имя).', '{"func": "best_host", "tests": [{"args": [{}], "expected": ""}, {"args": [{"a": {"gateway": true, "mgmt": true, "free_mb": 8000, "cpu": 10}}], "expected": "a"}, {"args": [{"a": {"gateway": false, "mgmt": true, "free_mb": 8000, "cpu": 10}, "b": {"gateway": true, "mgmt": true, "free_mb": 2000, "cpu": 10}}], "expected": "b"}, {"args": [{"b": {"gateway": true, "mgmt": true, "free_mb": 8000, "cpu": 10}, "a": {"gateway": true, "mgmt": true, "free_mb": 9000, "cpu": 20}}], "expected": "a"}, {"args": [{"x": {"gateway": false, "mgmt": false, "free_mb": 1, "cpu": 99}, "y": {"gateway": false, "mgmt": false, "free_mb": 1, "cpu": 99}}], "expected": "x"}, {"args": [{"h1": {"gateway": true, "mgmt": true, "free_mb": 5000, "cpu": 90}, "h2": {"gateway": true, "mgmt": false, "free_mb": 5000, "cpu": 10}}], "expected": "h2"}, {"args": [{"a": {"gateway": true, "mgmt": true, "free_mb": 8000, "cpu": 65}, "b": {"gateway": true, "mgmt": true, "free_mb": 8000, "cpu": 85}, "c": {"gateway": true, "mgmt": false, "free_mb": 8000, "cpu": 10}}], "expected": "a"}, {"args": [{"m": {"gateway": true, "mgmt": false, "free_mb": 8000, "cpu": 10}, "g": {"gateway": false, "mgmt": true, "free_mb": 8000, "cpu": 10}}], "expected": "m"}, {"args": [{"b": {"gateway": true, "mgmt": true, "free_mb": 8000, "cpu": 40}, "a": {"gateway": true, "mgmt": true, "free_mb": 8000, "cpu": 41}}], "expected": "b"}, {"args": [{"b": {"gateway": true, "mgmt": true, "free_mb": 8000, "cpu": 40}, "a": {"gateway": true, "mgmt": true, "free_mb": 8000, "cpu": 30}}], "expected": "a"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-placement-order', 12, 'func', 'Порядок хостов для размещения', 'Упрощённый планировщик размещает новую машину на наименее загруженный хост кластера. Дан инвентарь (центр данных → кластер → хост → список ВМ) и имя кластера cluster (имена кластеров уникальны во всём инвентаре). Напишите функцию placement_order(inventory, cluster): верните список имён хостов кластера, отсортированный по числу ВМ по возрастанию, а при равенстве — по имени. Если такого кластера нет, верните пустой список.', 'def placement_order(inventory, cluster):
    pass
', 'Найдите словарь хостов кластера в двух циклах, потом sorted(hosts, key=lambda h: (len(hosts[h]), h)).', '{"func": "placement_order", "tests": [{"args": [{"dc": {"c1": {"h1": ["a", "b"], "h2": ["c"], "h3": []}}}, "c1"], "expected": ["h3", "h2", "h1"]}, {"args": [{"dc": {"c1": {"h1": ["a"], "h2": ["b"]}}}, "c1"], "expected": ["h1", "h2"]}, {"args": [{"dc": {"c1": {"h1": []}}}, "zz"], "expected": []}, {"args": [{"d1": {"c1": {"x": ["1"]}}, "d2": {"c2": {"y": [], "a": ["1", "2"]}}}, "c2"], "expected": ["y", "a"]}, {"args": [{}, "c"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 17, 'ov-command-trace', 13, 'func', 'Где потеряно время', 'Команда запуска машины проходит звенья engine → vdsm → libvirt → qemu. Журнал трассировки — список кортежей (звено, начало, конец) в секундах; звенья вложены, поэтому собственное время звена — это его длительность минус длительность следующего звена в журнале (последнее звено считается целиком). Напишите функцию slowest_link(trace): верните имя звена с наибольшим собственным временем; при равенстве — то, что в журнале раньше. Для пустого журнала верните пустую строку.', 'def slowest_link(trace):
    pass
', 'Длительность = конец − начало; собственное время i-го звена = длительность i минус длительность i+1.', '{"func": "slowest_link", "tests": [{"args": [[]], "expected": ""}, {"args": [[{"__tuple__": ["engine", 0, 10]}, {"__tuple__": ["vdsm", 1, 9]}, {"__tuple__": ["libvirt", 2, 8]}, {"__tuple__": ["qemu", 3, 7]}]], "expected": "qemu"}, {"args": [[{"__tuple__": ["engine", 0, 10]}, {"__tuple__": ["vdsm", 5, 9]}, {"__tuple__": ["libvirt", 6, 8]}, {"__tuple__": ["qemu", 6, 7]}]], "expected": "engine"}, {"args": [[{"__tuple__": ["engine", 0, 10]}, {"__tuple__": ["vdsm", 1, 9]}, {"__tuple__": ["libvirt", 4, 6]}, {"__tuple__": ["qemu", 4, 5]}]], "expected": "vdsm"}, {"args": [[{"__tuple__": ["engine", 0, 4]}, {"__tuple__": ["vdsm", 0, 2]}]], "expected": "engine"}, {"args": [[{"__tuple__": ["engine", 0, 4]}, {"__tuple__": ["vdsm", 0, 4]}]], "expected": "vdsm"}]}');
